type ApiFixtureRequestHeaders = {
  origin?: string;
  'access-control-request-headers'?: string;
};

export function createApiFixtureCorsHeaders(
  requestHeaders: ApiFixtureRequestHeaders,
  fallbackOrigin: string,
): Record<string, string> {
  return {
    'access-control-allow-origin': requestHeaders.origin ?? fallbackOrigin,
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, PATCH, PUT, DELETE, OPTIONS',
    'access-control-allow-headers':
      requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };
}

import { readFileSync } from 'node:fs';
import { expect, test, type Page } from '@playwright/test';

type LandingCopy = Record<'titleLine1' | 'titleLine2' | 'lead' | 'ctaHome' | 'ctaOrganizer', string>;
const messagesPath = new URL('../../messages/vi.json', import.meta.url);
const copy = (JSON.parse(readFileSync(messagesPath, 'utf8')) as { Landing: LandingCopy }).Landing;
const globalHeader = 'header:not([data-scene] header)';
const globalFooter = 'footer:not([data-scene] footer)';

async function openLanding(page: Page) {
  await page.goto('/landing');
  await expect(page.locator('[data-scene]')).not.toHaveAttribute('data-scene', 'loading', { timeout: 30_000 });
}

test.describe('Landing /landing — nội dung, điều hướng, bố cục', () => {
  test('TC-LANDING-01 hiện tiêu đề, mô tả, 2 nút; không có chrome toàn cục', async ({ page }) => {
    await openLanding(page);
    await expect(page.getByRole('heading', { level: 1 })).toHaveText(`${copy.titleLine1}${copy.titleLine2}`);
    await expect(page.getByText(copy.lead)).toBeVisible();
    await expect(page.locator(globalHeader)).toHaveCount(0);
    await expect(page.locator(globalFooter)).toHaveCount(0);
  });

  test('TC-LANDING-02 nút trỏ đúng đích; về trang chủ thì chrome hiện lại', async ({ page }) => {
    await openLanding(page);
    const home = page.getByRole('link', { name: copy.ctaHome });
    await expect(home).toHaveAttribute('href', '/');
    await expect(page.getByRole('link', { name: copy.ctaOrganizer })).toHaveAttribute('href', '/organizer/tournaments');
    await home.click();
    await expect(page).toHaveURL(/\/$/);
    await expect(page.locator(globalHeader)).toHaveCount(1);
  });

  for (const viewport of [
    { width: 390, height: 844 },
    { width: 820, height: 1180 },
    { width: 1440, height: 900 },
  ]) {
    test(`TC-LANDING-03 ${viewport.width}x${viewport.height}: không tràn ngang, 2 nút trong màn đầu`, async ({ page }) => {
      await page.setViewportSize(viewport);
      await openLanding(page);
      const layout = await page.evaluate(() => ({
        scrollWidth: document.documentElement.scrollWidth,
        innerWidth: window.innerWidth,
        innerHeight: window.innerHeight,
        buttonBottoms: [...document.querySelectorAll('[data-scene] a')].map((a) => a.getBoundingClientRect().bottom),
      }));
      expect(layout.scrollWidth).toBeLessThanOrEqual(layout.innerWidth);
      expect(layout.buttonBottoms).toHaveLength(2);
      for (const bottom of layout.buttonBottoms) expect(bottom).toBeLessThanOrEqual(layout.innerHeight);
    });
  }

  test('TC-LANDING-04 không có WebGL: hiện hình thay thế, nút vẫn dùng được', async ({ page }) => {
    await page.addInitScript(() => {
      const original = HTMLCanvasElement.prototype.getContext;
      HTMLCanvasElement.prototype.getContext = function (this: HTMLCanvasElement, type: string, ...rest: unknown[]) {
        if (/webgl/i.test(type)) return null;
        return (original as (this: HTMLCanvasElement, ...args: unknown[]) => RenderingContext | null).call(this, type, ...rest);
      } as typeof HTMLCanvasElement.prototype.getContext;
    });
    await openLanding(page);
    await expect(page.locator('[data-scene]')).toHaveAttribute('data-scene', 'fallback');
    await expect(page.getByRole('link', { name: copy.ctaHome })).toBeVisible();
  });
});

