async function stubAccountLinkApi(
…
): Promise<AccountLinkStub> {
…
  await page.route('**/api/v1/**', async (route) => {
…
    if (pathname === `/api/v1/tournaments/${tournamentId}/participants/me/ranking-consent`) {
…
      if (options.consentStatus) {
        await fulfillApi(
…
          options.consentStatus,
        );
        return;
      }
      linked = true;
      await fulfillApi(route, {
        data: {
          participantId,
          consentedAt: confirmedAt,
          accountLinkConfirmedAt: confirmedAt,
          alreadyConfirmed: false,
        },
      });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

  return stub;
}

async function openTournamentDetail(page: Page, isRanked: boolean) {
  await page.goto(`/tournaments/${tournamentIdFor(isRanked)}`, { waitUntil: 'domcontentloaded' });
}

/**
 * The visible banner's text column: title, copy and button share this parent. The DOM also keeps
 * a hidden copy for the other breakpoint, so only the visible title is matched.
 */
function pendingBanner(page: Page) {
  return page.getByText(pendingTitle).filter({ visible: true }).locator('..');
}

/** Visible error toasts with the server-busy copy; counted so a duplicate toast fails the test. */
function serverBusyToasts(page: Page) {
  return page.getByText(serverBusyMessage).filter({ visible: true });
}

for (const isRanked of [true, false]) {
  test(`shows the pending account-link banner with the ${isRanked ? 'ranked' : 'unranked'} copy`, async ({ page }) => {
    await stubAccountLinkApi(page, { isRanked });
    await openTournamentDetail(page, isRanked);

    const banner = pendingBanner(page);
    await expect(page.getByText(pendingTitle).filter({ visible: true })).toBeVisible({ timeout: 30_000 });
    await expect(banner.getByText(isRanked ? rankedCopy : unrankedCopy)).toBeVisible();
    await expect(banner.getByText(isRanked ? unrankedCopy : rankedCopy)).toHaveCount(0);
    await expect(banner.getByRole('button', { name: confirmLabel })).toBeVisible();
  });
}

test('confirms once and drops the banner after the registration reloads', async ({ page }) => {
  const stub = await stubAccountLinkApi(page, { isRanked: true });
  await openTournamentDetail(page, true);

  const confirm = pendingBanner(page).getByRole('button', { name: confirmLabel });
  await expect(confirm).toBeVisible({ timeout: 30_000 });
  const readsBeforeConfirm = stub.registrationReads;
  await confirm.click();

  await expect(page.getByText(confirmedToast)).toBeVisible();
  await expect(page.getByText(pendingTitle)).toHaveCount(0);
  expect(stub.consentRequests).toBe(1);
  expect(stub.registrationReads).toBeGreaterThan(readsBeforeConfirm);
});

test('keeps the banner and shows the error when confirmation fails', async ({ page }) => {
  const stub = await stubAccountLinkApi(page, { isRanked: true, consentStatus: 500 });
  await openTournamentDetail(page, true);

  const confirm = pendingBanner(page).getByRole('button', { name: confirmLabel });
  await expect(confirm).toBeVisible({ timeout: 30_000 });
  await confirm.click();

  await expect(serverBusyToasts(page)).toHaveCount(1);
  await expect(page.getByText(pendingTitle).filter({ visible: true })).toBeVisible();
  await expect(confirm).toBeEnabled();
  expect(stub.consentRequests).toBe(1);
});

test('shows one error toast per failed confirmation, including inside the server-error cooldown', async ({ page }) => {
  const stub = await stubAccountLinkApi(page, { isRanked: true, consentStatus: 500 });
  await openTournamentDetail(page, true);

  const confirm = pendingBanner(page).getByRole('button', { name: confirmLabel });
  await expect(confirm).toBeVisible({ timeout: 30_000 });

  await confirm.click();
  await expect(serverBusyToasts(page)).toHaveCount(1);
  // Let the first toast auto-dismiss so the next count proves a fresh toast, not the old one.
  await expect(serverBusyToasts(page)).toHaveCount(0, { timeout: 15_000 });
  // The second click should still fall inside the 10 s global cooldown the first failure started. If toast lifetime grows past 10 s, this test stops covering the cooldown.
  await confirm.click();
  await expect(serverBusyToasts(page)).toHaveCount(1);
…
