import { expect, test, type Page } from '@playwright/test';

import { fulfillApi } from './support/organizer-manage';

// One synthetic tournament per copy variant. SSR reads `isRanked` from the mock fixture, not from the client stub.
const rankedTournamentId = 'synthetic-account-link-tournament';
const unrankedTournamentId = 'synthetic-account-link-unranked-tournament';
function tournamentIdFor(isRanked: boolean): string {
  return isRanked ? rankedTournamentId : unrankedTournamentId;
}

const divisionId = 'synthetic-account-link-division';
const participantId = 'synthetic-account-link-participant';
const confirmedAt = '2026-10-12T08:00:00.000Z';

// Test-only account: every address is a synthetic `.test` domain.
const player = {
  id: 'synthetic-account-link-player',
  email: 'account-link-player@example.test',
  fullName: 'Người chơi liên kết thử nghiệm',
  phoneNumber: '0900000002',
  roles: ['USER'],
  gender: 'MALE',
};

// `/users/profile` answers with the standard envelope that usersApi.getProfile unwraps.
const profileResponse = {
  data: {
    id: player.id,
    email: player.email,
    isEmailVerified: true,
    isPhoneVerified: true,
    roles: player.roles,
    profile: {
      fullName: player.fullName,
      phoneNumber: player.phoneNumber,
      gender: player.gender,
    },
  },
};

const division = {
  id: divisionId,
  name: 'Synthetic account link division',
  matchType: 'SINGLES',
  genderRestriction: 'MALE',
  entryFee: 0,
  maxParticipants: 16,
  bracketType: 'ROUND_ROBIN',
  _count: { participants: 1 },
};

const tournament = {
  name: 'Synthetic account link tournament',
  status: 'PUBLISHED',
  matchType: 'SINGLES',
  genderRestriction: 'MALE',
  entryFee: 0,
  maxParticipants: 16,
  isRegistrationLocked: false,
  category: { name: 'Badminton', slug: 'badminton' },
  tournamentConfig: { registrationMode: 'OPEN' },
};

